module multiple_counter (\n    input clk,\n    input rst_n,\n    input start,\n    input [15:0] X,\n    input [15:0] A,\n    input [15:0] B,\n    input [9:0] allowed_mask,\n    output reg [15:0] count,\n    output reg done\n);\n\n    // State encoding\n    localparam [2:0] IDLE          = 3'd0;\n    localparam [2:0] CHECK         = 3'd1;\n    localparam [2:0] CHECK_DIGITS  = 3'd2;\n    localparam [2:0] EXTRACT_DIGIT = 3'd3;\n    localparam [2:0] COUNT         = 3'd4;\n    localparam [2:0] INCREMENT     = 3'd5;\n    localparam [2:0] DONE_STATE    = 3'd6;\n    \n    reg [2:0] state;\n    reg [15:0] current;\n    reg [15:0] rem;\n    reg [15:0] temp_count;\n    reg [15:0] temp_num;\n    reg valid;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            current <= 16'd0;\n            rem <= 16'd0;\n            temp_count <= 16'd0;\n            temp_num <= 16'd0;\n            valid <= 1'b0;\n            done <= 1'b0;\n            count <= 16'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        current <= A;\n                        rem <= A % X;\n                        temp_count <= 16'd0;\n                        state <= CHECK;\n                    end\n                end\n                \n                CHECK: begin\n                    if (current > B) begin\n                        count <= temp_count;\n                        state <= DONE_STATE;\n                    end else begin\n                        if (rem == 16'd0) begin\n                            state <= CHECK_DIGITS;\n                            valid <= 1'b1;\n                        end else begin\n                            state <= INCREMENT;\n                        end\n                    end\n                end\n                \n                CHECK_DIGITS: begin\n                    if (current == 16'd0) begin\n                        if (allowed_mask[0]) state <= COUNT;\n                        else state <= INCREMENT;\n                    end else begin\n                        temp_num <= current;\n                        state <= EXTRACT_DIGIT;\n                    end\n                end\n                \n                EXTRACT_DIGIT: begin\n                    if (allowed_mask[temp_num % 4'd10] == 1'b0) begin\n                        valid <= 1'b0;\n                    end\n                    temp_num <= temp_num / 4'd10;\n                    if (temp_num <= 4'd10) begin  // Last digit check\n                        if (valid) state <= COUNT;\n                        else state <= INCREMENT;\n                    end\n                end\n                \n                COUNT: begin\n                    temp_count <= temp_count + 16'd1;\n                    state <= INCREMENT;\n                end\n                \n                INCREMENT: begin\n                    current <= current + 16'd1;\n                    rem <= (rem + 16'd1 < X) ? rem + 16'd1 : 16'd0;\n                    state <= CHECK;\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule